mapper.update:
UPDATE storybooks
SET is_public = #{isPublic}
WHERE id = #{storyId}

mapper.select:
SELECT s.id AS storyId, s.plan_id AS planId, p.title AS planTitle, s.title, DATE_FORMAT(s.created_at, '%Y-%m-%d') AS createdDate, s.thumbnail_path AS thumbnailPath, s.is_public AS isPublic FROM storybooks s LEFT JOIN plans p ON s.plan_id = p.id WHERE s.member_id = #{memberId}
AND s.plan_id = #{planId}
ORDER BY s.created_at DESC
